"use client";

import { useId, useState } from "react";

import { SparklesIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { cn } from "@/lib/utils";

import { STATUS_SURFACE, STATUS_TEXT, type Status } from "../lib/status";
import { BlockFrame } from "../parts/block-frame";
import { ClipPlayer } from "./call-insights/clip-player";
import {
  CALL_SECONDS,
  KIND_STYLE,
  MOMENTS,
  NEXT_STEPS,
  SPEAKERS,
  SUMMARY,
  formatClock,
} from "./call-insights/data";
import { MomentRail } from "./call-insights/moment-rail";
import { CopyIcon } from "./icons";
import { Initials } from "./parts/initials";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

const RISK: { status: Status; word: string }[] = [
  { status: "bad", word: "High risk" },
  { status: "watch", word: "Medium risk" },
  { status: "good", word: "Low risk" },
  { status: "good", word: "Low risk" },
];

/**
 * A sales call, read back: who talked how much, the flagged moments on a
 * timeline, the quote and clip of the chosen moment, a summary and the next
 * steps. Ticking next steps lowers the deal risk.
 */
export function CallInsights({ className }: { className?: string }) {
  const [selected, setSelected] = useState(1);
  const [done, setDone] = useState<string[]>([]);
  const [copied, setCopied] = useState<string | null>(null);
  const titleId = useId();
  const moment = MOMENTS[selected] ?? MOMENTS[0]!;
  const risk = RISK[done.length] ?? RISK[0]!;

  const toggle = (id: string, checked: boolean) =>
    setDone(checked ? [...done, id] : done.filter((item) => item !== id));

  const copy = () => {
    void navigator.clipboard?.writeText(moment.quote).catch(() => undefined);
    setCopied(moment.id);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-start justify-between gap-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Discovery call with Lakeside Physio
          </h2>
          <p className="text-sm text-muted-foreground tabular-nums">
            Recorded by Callnote, Oct 28, {Math.round(CALL_SECONDS / 60)} min
          </p>
        </div>
        <div className="flex items-center gap-3">
          <span
            role="status"
            className={cn(
              "rounded-full px-2.5 py-0.5 text-xs font-medium",
              STATUS_SURFACE[risk.status],
              STATUS_TEXT[risk.status],
            )}
          >
            {risk.word}
          </span>
          <ul aria-label="Attendees" className="flex -space-x-2">
            {SPEAKERS.map((speaker, index) => (
              <li key={speaker.id}>
                <Initials name={speaker.name} tint={index} />
                <span className="sr-only">
                  {speaker.name}, {speaker.side}
                </span>
              </li>
            ))}
          </ul>
        </div>
      </header>

      <div className="flex flex-col gap-5 p-5">
        <section
          aria-labelledby={`${titleId}-talk`}
          className="flex flex-col gap-2"
        >
          <h3
            id={`${titleId}-talk`}
            className="text-xs font-medium text-muted-foreground"
          >
            Talk time
          </h3>
          <div
            aria-hidden="true"
            className="flex h-2.5 gap-0.5 overflow-hidden rounded-full"
          >
            {SPEAKERS.map((speaker) => (
              <span
                key={speaker.id}
                className={cn("h-full w-(--w)", speaker.bar)}
                style={
                  // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                  { "--w": `${speaker.share}%` } as VarStyle
                }
              />
            ))}
          </div>
          <ul className="flex flex-wrap gap-x-4 gap-y-1 text-xs">
            {SPEAKERS.map((speaker) => (
              <li key={speaker.id} className="flex items-center gap-1.5">
                <span
                  aria-hidden="true"
                  className={cn("size-2 rounded-full", speaker.bar)}
                />
                <span className="text-muted-foreground">{speaker.name}</span>
                <span className="font-medium tabular-nums">
                  {speaker.share}%
                </span>
              </li>
            ))}
          </ul>
        </section>

        <section
          aria-labelledby={`${titleId}-moments`}
          className="flex flex-col gap-3"
        >
          <div className="flex flex-wrap items-center justify-between gap-2">
            <h3
              id={`${titleId}-moments`}
              className="text-xs font-medium text-muted-foreground"
            >
              Flagged moments
            </h3>
            <ul
              aria-label="Moment key"
              className="flex flex-wrap gap-3 text-xs text-muted-foreground"
            >
              {Object.values(KIND_STYLE).map((style) => (
                <li key={style.label} className="flex items-center gap-1.5">
                  <span
                    aria-hidden="true"
                    className={cn("size-2 rounded-full", style.dot)}
                  />
                  {style.label}
                </li>
              ))}
            </ul>
          </div>
          <MomentRail
            moments={MOMENTS}
            selected={selected}
            onSelect={setSelected}
          />

          <div className="flex flex-col gap-3 rounded-xl border border-border p-4">
            <div aria-live="polite" className="grid">
              {MOMENTS.map((item) => {
                const speaker = SPEAKERS.find(
                  (person) => person.id === item.speaker,
                );
                const shown = item === moment;
                const style = KIND_STYLE[item.kind];
                return (
                  <figure
                    key={item.id}
                    aria-hidden={!shown}
                    className={cn(
                      "col-start-1 row-start-1 flex flex-col gap-2 motion-safe:transition-opacity motion-safe:duration-200",
                      shown ? "opacity-100" : "pointer-events-none opacity-0",
                    )}
                  >
                    <figcaption className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
                      <Initials
                        name={speaker?.name ?? ""}
                        tint={SPEAKERS.indexOf(speaker ?? SPEAKERS[0]!)}
                        className="size-6 text-xs"
                      />
                      <span className="font-medium text-foreground">
                        {speaker?.name}
                      </span>
                      <span
                        className={cn(
                          "rounded-full px-2 py-0.5 font-medium",
                          style.pill,
                        )}
                      >
                        {style.label}
                      </span>
                      <span className="tabular-nums">
                        {formatClock(item.at)}
                      </span>
                    </figcaption>
                    <blockquote className="text-sm leading-relaxed text-balance">
                      {item.quote}
                    </blockquote>
                  </figure>
                );
              })}
            </div>
            <div className="flex items-center gap-2">
              <div className="min-w-0 flex-1">
                <ClipPlayer
                  seconds={moment.clip}
                  seed={moment.seed}
                  label={`clip at ${formatClock(moment.at)}`}
                />
              </div>
              <Button
                variant="ghost"
                size="icon"
                className="size-9"
                aria-label={
                  copied === moment.id ? "Quote copied" : "Copy quote"
                }
                onClick={copy}
              >
                <CopyIcon aria-hidden="true" className="size-4" />
              </Button>
            </div>
          </div>
        </section>

        <div className="grid gap-5 @2xl:grid-cols-2">
          <section
            aria-labelledby={`${titleId}-summary`}
            className="flex flex-col gap-2"
          >
            <h3
              id={`${titleId}-summary`}
              className="flex items-center gap-1.5 text-xs font-medium text-muted-foreground"
            >
              <SparklesIcon
                aria-hidden="true"
                className="size-3.5 text-chart-4"
              />
              Summary
            </h3>
            <p className="text-sm leading-relaxed">{SUMMARY}</p>
          </section>
          <section
            aria-labelledby={`${titleId}-steps`}
            className="flex flex-col gap-2"
          >
            <h3
              id={`${titleId}-steps`}
              className="text-xs font-medium text-muted-foreground"
            >
              Next steps
            </h3>
            <ul className="flex flex-col gap-1">
              {NEXT_STEPS.map((step) => {
                const checked = done.includes(step.id);
                return (
                  <li key={step.id}>
                    <label className="flex min-h-11 cursor-pointer items-start gap-3 rounded-lg px-2 py-2 hover:bg-muted">
                      <Checkbox
                        checked={checked}
                        onCheckedChange={(value) =>
                          toggle(step.id, value === true)
                        }
                        className="mt-0.5"
                      />
                      <span className="flex min-w-0 flex-col">
                        <span
                          className={cn(
                            "text-sm",
                            checked
                              ? "text-muted-foreground line-through"
                              : undefined,
                          )}
                        >
                          {step.text}
                        </span>
                        <span className="text-xs text-muted-foreground">
                          {step.owner}
                        </span>
                      </span>
                    </label>
                  </li>
                );
              })}
            </ul>
          </section>
        </div>
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
