/** Six dots, for a handle a person drags. */
export const GripVerticalIcon = ownIcon(
  <path d="M6 3.5h.01M10 3.5h.01M6 8h.01M10 8h.01M6 12.5h.01M10 12.5h.01" strokeWidth="2" />,
);

/** Two bars, for pause. */
export const PlayerPauseFilledIcon = ownIcon(<path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />);

/** A bin, for remove. */
export const TrashIcon = ownIcon(
  <>
    <path d="M2.5 4.5h11M6 4.5V3a.5.5 0 0 1 .5-.5h3A.5.5 0 0 1 10 3v1.5" />
    <path d="M4 4.5l.6 8a1 1 0 0 0 1 .9h4.8a1 1 0 0 0 1-.9l.6-8M6.75 7v4M9.25 7v4" />
  </>,
);

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { type KeyboardEvent, useEffect, useRef, useState } from "react";

import {
  PlayerPauseFilledIcon,
  PlayerPlayFilledIcon,
} from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { seededRandom } from "../../lib/plot";
import { formatClock } from "./data";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for a short clip with its waveform. */
export interface ClipPlayerProps {
  /** Length of the clip in seconds. */
  seconds: number;
  /** Seeds the waveform shape. */
  seed: number;
  /** Names the clip for the play button and the seek bar. */
  label: string;
}

const BARS = 44;
const STEP_MS = 100;

/** The bar heights of a clip, from 20 to 100 percent, smoothed so the shape reads as speech. */
function waveform(seed: number): number[] {
  const random = seededRandom(seed);
  const raw = Array.from({ length: BARS }, () => random());
  return raw.map((value, index) => {
    const near =
      ((raw[index - 1] ?? value) + value * 2 + (raw[index + 1] ?? value)) / 4;
    return 20 + near * 80;
  });
}

/**
 * Play and a waveform that doubles as a seek bar. A new clip reshapes the same bars. Playback is simulated with
 * an interval that is cleared on pause, at the end and on unmount. Arrows
 * seek one second, Home and End jump to the ends.
 */
export function ClipPlayer({ seconds, seed, label }: ClipPlayerProps) {
  const [position, setPosition] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [forSeed, setForSeed] = useState(seed);
  const positionRef = useRef(0);
  // A new clip starts at its beginning, stopped. The bars keep their elements, so they reshape to the new clip.
  if (forSeed !== seed) {
    setForSeed(seed);
    setPosition(0);
    setPlaying(false);
  }
  useEffect(() => {
    positionRef.current = position;
  }, [position]);
  const steps = seconds * (1000 / STEP_MS);
  const bars = waveform(seed);

  useEffect(() => {
    if (!playing) return;
    const id = window.setInterval(() => {
      positionRef.current = Math.min(steps, positionRef.current + 1);
      setPosition(positionRef.current);
      if (positionRef.current >= steps) setPlaying(false);
    }, STEP_MS);
    return () => window.clearInterval(id);
  }, [playing, steps]);

  const seek = (next: number) => {
    positionRef.current = Math.max(0, Math.min(steps, next));
    setPosition(positionRef.current);
  };

  const toggle = () => {
    if (!playing && positionRef.current >= steps) seek(0);
    setPlaying(!playing);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const second = 1000 / STEP_MS;
    if (event.key === "ArrowRight" || event.key === "ArrowUp")
      seek(position + second);
    else if (event.key === "ArrowLeft" || event.key === "ArrowDown")
      seek(position - second);
    else if (event.key === "Home") seek(0);
    else if (event.key === "End") seek(steps);
    else return;
    event.preventDefault();
  };

  const played = position / steps;
  const elapsed = (position * STEP_MS) / 1000;

  return (
    <div className="flex items-center gap-3">
      <Button
        size="icon"
        className="size-9"
        aria-label={`${playing ? "Pause" : "Play"} ${label}`}
        onClick={toggle}
      >
        {playing ? (
          <PlayerPauseFilledIcon aria-hidden="true" />
        ) : (
          <PlayerPlayFilledIcon aria-hidden="true" className="size-4" />
        )}
      </Button>
      <div
        role="slider"
        tabIndex={0}
        aria-label={`Seek in ${label}`}
        aria-valuemin={0}
        aria-valuemax={seconds}
        aria-valuenow={Math.round(elapsed)}
        aria-valuetext={`${formatClock(elapsed)} of ${formatClock(seconds)}`}
        onKeyDown={onKeyDown}
        onPointerDown={(event) => {
          const box = event.currentTarget.getBoundingClientRect();
          seek(Math.round(((event.clientX - box.left) / box.width) * steps));
        }}
        className="flex h-9 min-w-0 flex-1 cursor-pointer touch-pan-y items-center gap-px rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card"
      >
        {bars.map((height, index) => (
          <span
            key={index}
            aria-hidden="true"
            className={cn(
              "h-(--h) flex-1 rounded-full motion-safe:transition-all motion-safe:duration-300",
              index / BARS < played ? "bg-chart-1" : "bg-muted-foreground/30",
            )}
            style={
              // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
              { "--h": `${height}%` } as VarStyle
            }
          />
        ))}
      </div>
      <span className="w-20 text-right text-xs text-muted-foreground tabular-nums">
        {formatClock(elapsed)} / {formatClock(seconds)}
      </span>
    </div>
  );
}

/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

