/** A time in the call, such as 4:12. */
export function formatClock(seconds: number): string {
  const whole = Math.max(0, Math.floor(seconds));
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, "0")}`;
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };

"use client";

import type { KeyboardEvent } from "react";

import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { cn } from "@/lib/utils";

import {
  CALL_SECONDS,
  KIND_STYLE,
  type Moment,
  SPEAKERS,
  formatClock,
} from "./data";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for the timeline of flagged moments. */
export interface MomentRailProps {
  moments: Moment[];
  selected: number;
  onSelect: (index: number) => void;
}

/**
 * The call as one line with a marker for each flagged moment. The line fills
 * up to the chosen marker in one move. It is a radio group: Tab reaches the
 * chosen marker, arrows move between moments, Home and End jump to the ends.
 */
export function MomentRail({ moments, selected, onSelect }: MomentRailProps) {
  const chosen = moments[selected];

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const next =
      event.key === "Home"
        ? 0
        : event.key === "End"
          ? moments.length - 1
          : null;
    if (next === null) return;
    event.preventDefault();
    onSelect(next);
    const radios =
      event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="radio"]');
    radios[next]?.focus();
  };

  return (
    <div className="flex flex-col gap-1">
      <div className="mx-2.5">
        <RadioGroup
          aria-label="Flagged moments"
          value={String(selected)}
          onValueChange={(value) => onSelect(Number(value))}
          onKeyDown={onKeyDown}
          className="relative block h-8"
        >
          <span
            aria-hidden="true"
            className="absolute inset-x-0 top-1/2 h-1 -translate-y-1/2 rounded-full bg-muted"
          />
          <span
            aria-hidden="true"
            className="absolute top-1/2 left-0 h-1 w-(--w) -translate-y-1/2 rounded-full bg-foreground/70 motion-safe:transition-all motion-safe:duration-300 motion-safe:ease-out"
            style={
              // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
              {
                "--w": `${((chosen?.at ?? 0) / CALL_SECONDS) * 100}%`,
              } as VarStyle
            }
          />
          {moments.map((moment, index) => {
            const style = KIND_STYLE[moment.kind];
            const checked = index === selected;
            const speaker = SPEAKERS.find((item) => item.id === moment.speaker);
            return (
              <label
                key={moment.id}
                className="group absolute top-1/2 left-(--x) flex size-8 -translate-x-1/2 -translate-y-1/2 cursor-pointer items-center justify-center rounded-full outline-none has-focus-visible:ring-2 has-focus-visible:ring-ring"
                style={
                  // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                  { "--x": `${(moment.at / CALL_SECONDS) * 100}%` } as VarStyle
                }
              >
                <RadioGroupItem
                  value={String(index)}
                  aria-label={`${style.label} at ${formatClock(moment.at)}, ${speaker?.name ?? ""}`}
                  className="sr-only"
                />
                <span
                  aria-hidden="true"
                  className={cn(
                    "block rounded-full ring-2 ring-card motion-safe:transition-transform",
                    style.dot,
                    checked
                      ? "size-4"
                      : "size-3 opacity-80 group-hover:scale-125",
                  )}
                />
              </label>
            );
          })}
        </RadioGroup>
      </div>
      <div
        aria-hidden="true"
        className="flex justify-between text-xs text-muted-foreground tabular-nums"
      >
        <span>0:00</span>
        <span>{formatClock(CALL_SECONDS)}</span>
      </div>
    </div>
  );
}

