/** The tinted surface and ink pairs a person's initials can sit on. Each pair passes contrast in both themes. */
const TINTS = [
  "bg-marketing-blue-surface text-marketing-blue-ink",
  "bg-marketing-green-surface text-marketing-green-ink",
  "bg-marketing-orange-surface text-marketing-orange-ink",
  "bg-marketing-purple-surface text-marketing-purple-ink",
  "bg-marketing-pink-surface text-marketing-pink-ink",
  "bg-marketing-amber-surface text-marketing-amber-ink",
];

/** Props for a person's initials. */
export interface InitialsProps {
  name: string;
  /** Picks the tint, so the same person keeps one colour across a block. */
  tint: number;
  className?: string;
}

/** A person's initials in a tinted circle. Decorative: the name always sits beside it or in a label. */
export function Initials({ name, tint, className }: InitialsProps) {
  const letters = name
    .split(" ")
    .filter((part) => /^[A-Z]/.test(part))
    .map((part) => part[0])
    .slice(0, 2)
    .join("");
  return (
    <span
      aria-hidden="true"
      className={cn(
        "inline-flex size-7 shrink-0 items-center justify-center rounded-full text-xs font-semibold ring-2 ring-card",
        TINTS[tint % TINTS.length],
        className,
      )}
    >
      {letters}
    </span>
  );
}
